<?php
namespace App\Services;
use App\Models\PayrollLine;
class PayslipPdfService { public function render(PayrollLine $line):string{$lines=['LORINE PAYSLIP','Employee: '.$line->membership->user->name,'Period: '.$line->period->period,'Currency: '.$line->currency,'Gross: '.$line->gross_amount,'Adjustments: '.$line->adjustment_amount,'Net: '.$line->net_amount];$stream="BT\n/F1 16 Tf\n50 790 Td\n";foreach($lines as $i=>$lineText){if($i)$stream.="0 -20 Td\n";$stream.='('.str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$lineText).") Tj\n";}$stream.="ET\n";$objects=["<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>","<< /Length ".strlen($stream)." >>\nstream\n".$stream."endstream"];$pdf="%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";$offsets=[];foreach($objects as $i=>$object){$offsets[]=strlen($pdf);$pdf.=($i+1)." 0 obj\n".$object."\nendobj\n";}$xref=strlen($pdf);$pdf.="xref\n0 6\n0000000000 65535 f \n";foreach($offsets as $offset)$pdf.=sprintf('%010d 00000 n ',$offset)."\n";return $pdf."trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n".$xref."\n%%EOF";} }
